6	import { fetchArtificialAnalysisData } from "./artificial-analysis/fetch.ts";
7	import { copilotSource } from "./copilot/source.ts";
8	import { updateModelMapping } from "./mapping/update-mapping.ts";
9	import { openCodeGoSource } from "./opencode-go/source.ts";
10	import { refreshPricingSource } from "./pricing/refresh.ts";
11	import { computeScores } from "./scoring/compute-scores.ts";
12	
13	try {
14	  if (!existsSync(".env")) {
15	    console.error("Missing .env. Copy .env.example to .env and fill in AA_API_KEY before running.");
16	    process.exit(1);
17	  }
18	
19	  console.log("== Step 1/5: refreshing GitHub Copilot pricing ==");
20	  const copilotOk = await refreshPricingSource(copilotSource);
21	
22	  console.log("\n== Step 2/5: refreshing OpenCode Go pricing ==");
23	  const openCodeGoOk = await refreshPricingSource(openCodeGoSource);
24	
25	  console.log("\n== Step 3/5: fetching Artificial Analysis benchmark data ==");
26	  await fetchArtificialAnalysisData();
27	
28	  console.log("\n== Step 4/5: updating model mapping ==");
29	  await updateModelMapping();
30	
31	  console.log("\n== Step 5/5: scoring models per category ==");
32	  await computeScores();
33	
34	  if (!copilotOk || !openCodeGoOk) {
35	    console.error("\nDone with parser failures; some pricing data is stale (see errors above).");
